def count_squares(lines):
    count = 0
    n = len(lines)
    m = len(lines[0])

    # Helper function to check if a square is valid
    def is_valid_square(x, y, size):
        if x + size > n or y + size > m:
            return False
        for i in range(size):
            for j in range(size):
                if lines[x + i][y + j] != '+':
                    return False
        return True

    # Iterate over all potential center points
    for i in range(n):
        for j in range(m):
            # Check all possible square sizes starting from 2
            for size in range(2, min(n - i, m - j) + 1):
                if is_valid_square(i, j, size):
                    count += 1

    return count

